  ('animal_husbandry', 'Animal Husbandry', 'ancient', 25, 'Domesticate animals for food and labor.', ARRAY[]::text[], ARRAY['cattle', 'horses', 'sheep', 'goats', 'pigs', 'chickens', 'wool', 'milk']::text[], ARRAY['ranch']::text[], ARRAY['cavalry_scout']::text[], ARRAY['tannery', 'dairy']::text[]),
  ('agriculture', 'Agriculture', 'ancient', 25, 'Tame the land. Grow staple crops.', ARRAY[]::text[], ARRAY['wheat', 'barley', 'rye', 'oats', 'millet', 'sorghum', 'flour', 'flax']::text[], ARRAY['granary', 'farm']::text[], ARRAY[]::text[], ARRAY['milling']::text[]),
  ('mining', 'Mining', 'ancient', 25, 'Extract stone and minerals from the earth.', ARRAY[]::text[], ARRAY['flint', 'granite', 'marble', 'limestone', 'sandstone', 'slate', 'basalt', 'obsidian', 'clay', 'sand', 'gravel', 'salt', 'gypsum', 'quartz', 'iron-ore', 'hematite', 'magnetite', 'coal', 'flint', 'tin-ore', 'copper-ore']::text[], ARRAY['quarry', 'mine']::text[], ARRAY[]::text[], ARRAY['smelting']::text[]),
  ('pottery', 'Pottery', 'ancient', 30, 'Fired clay containers — the first storehouses.', ARRAY['mining']::text[], ARRAY['clay']::text[], ARRAY['granary']::text[], ARRAY[]::text[], ARRAY[]::text[]),
  ('sailing', 'Sailing', 'ancient', 30, 'Cross the water; trade and fish the seas.', ARRAY[]::text[], ARRAY['fish', 'fish-stocks', 'salt']::text[], ARRAY['harbor']::text[], ARRAY['galley']::text[], ARRAY['fishing']::text[]),
  ('writing', 'Writing', 'ancient', 50, 'Record knowledge and pass it to the next generation.', ARRAY['pottery']::text[], ARRAY['papyrus', 'parchment']::text[], ARRAY['library']::text[], ARRAY[]::text[], ARRAY['papermaking']::text[]),
  ('bronze_working', 'Bronze Working', 'ancient', 60, 'Alloy copper with tin to forge stronger tools.', ARRAY['mining']::text[], ARRAY['copper', 'tin', 'bronze']::text[], ARRAY['smithy']::text[], ARRAY['warrior', 'spearman']::text[], ARRAY['bronze_casting']::text[]),
  ('iron_working', 'Iron Working', 'ancient', 90, 'Smelt iron ore into the metal that builds empires.', ARRAY['bronze_working']::text[], ARRAY['iron', 'cast-iron']::text[], ARRAY['smithy']::text[], ARRAY['swordsman']::text[], ARRAY['iron_smelting']::text[]),
