  ('code_of_laws', 'Code of Laws', 'ancient', 90, 'Order the state with written law.', ARRAY['writing']::text[], ARRAY[]::text[], ARRAY['court']::text[], ARRAY[]::text[], ARRAY[]::text[]),
  ('currency', 'Currency', 'classical', 120, 'Coinage enables trade and treasuries.', ARRAY['code_of_laws']::text[], ARRAY['gold', 'silver', 'copper', 'gold-ore', 'silver-ore', 'gold-ore']::text[], ARRAY['market']::text[], ARRAY[]::text[], ARRAY['minting']::text[]),
  ('construction', 'Construction', 'classical', 120, 'Master masonry and build on a grand scale.', ARRAY['masonry']::text[], ARRAY['cement', 'concrete', 'brick']::text[], ARRAY['aqueduct', 'walls']::text[], ARRAY['catapult']::text[], ARRAY['cementmaking', 'concretemaking']::text[]),
  ('masonry', 'Masonry', 'classical', 90, 'Quarry and shape stone into monuments.', ARRAY['mining']::text[], ARRAY['marble']::text[], ARRAY['monument']::text[], ARRAY[]::text[], ARRAY[]::text[]),
  ('philosophy', 'Philosophy', 'classical', 150, 'Question everything. Double your science.', ARRAY['writing']::text[], ARRAY[]::text[], ARRAY['academy']::text[], ARRAY[]::text[], ARRAY[]::text[]),
