  ('engineering', 'Engineering', 'classical', 160, 'Build roads, bridges, and war engines.', ARRAY['mathematics']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['catapult']::text[], ARRAY[]::text[]),
