  ('glassblowing', 'Glassblowing', 'classical', 130, 'Turn sand into wonder.', ARRAY['pottery']::text[], ARRAY['glass']::text[], ARRAY['glassworks']::text[], ARRAY[]::text[], ARRAY['glassmaking']::text[]),
