  ('machinery', 'Machinery', 'medieval', 300, 'Cams, gears, and mills magnify labor.', ARRAY['engineering']::text[], ARRAY['machinery']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[]),
  ('gunpowder', 'Gunpowder', 'renaissance', 320, 'Fire and brimstone change warfare forever.', ARRAY['machinery']::text[], ARRAY['saltpeter', 'explosives']::text[], ARRAY['arsenal']::text[], ARRAY['musketman', 'bombard', 'cannon']::text[], ARRAY['gunpowder_recipe']::text[]),
