  ('chemistry', 'Chemistry', 'renaissance', 420, 'Mix the elements into new substances.', ARRAY['metallurgy']::text[], ARRAY['fertilizer', 'chemicals', 'pharmaceuticals', 'synthetic-rubber', 'nitrates', 'phosphates', 'ammonia', 'red-dye', 'blue-dye', 'green-dye', 'yellow-dye', 'orange-dye', 'purple-dye', 'black-dye', 'white-dye', 'brown-dye', 'pink-dye', 'rubber']::text[], ARRAY['laboratory', 'factory']::text[], ARRAY[]::text[], ARRAY['chemical_synthesis', 'fertilizermaking', 'dyesynthesis']::text[]),
