  ('steel_making', 'Steel Making', 'industrial', 500, 'The backbone of the industrial age.', ARRAY['steam_power']::text[], ARRAY['steel', 'stainless-steel']::text[], ARRAY['foundry']::text[], ARRAY[]::text[], ARRAY['steelmaking']::text[]),
